-- Add a reusable 200-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'sinh-hoat-tai-trung-quoc-200-cau',
  'Sinh hoạt tại Trung Quốc - 200 câu',
  '200 câu tiếng Trung HSK1-HSK3 dùng trong sinh hoạt tại Trung Quốc: thuê nhà, điện nước, sửa chữa, giao hàng, hỏi đường, đi lại, WeChat, thanh toán và xử lý vấn đề hằng ngày. Mỗi câu có pinyin, nghĩa tiếng Việt, 1-2 từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'sinh-hoat-tai-trung-quoc-200-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('这个房间还有空吗？', 'Zhè ge fángjiān hái yǒu kòng ma？', 'Phòng này còn trống không?', '[{"chinese":"空","pinyin":"kòng","meaning_vi":"trống, còn chỗ trống"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-52a4e0b1a43820e7ac36ef22.mp3', 1),
    ('我们可以预约看房吗？', 'Wǒmen kěyǐ yùyuē kàn fáng ma？', 'Chúng tôi có thể đặt lịch xem nhà không?', '[{"chinese":"预约","pinyin":"yùyuē","meaning_vi":"đặt lịch hẹn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-97b08d8024edf9c766c02978.mp3', 2),
    ('这里离地铁站远吗？', 'Zhèlǐ lí dìtiě zhàn yuǎn ma？', 'Ở đây cách ga tàu điện ngầm có xa không?', '[{"chinese":"地铁站","pinyin":"dìtiě zhàn","meaning_vi":"ga tàu điện ngầm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-fd5cb0fbdca301ed2a8ac47e.mp3', 3),
    ('我想租整套房子，方便吗？', 'Wǒ xiǎng zū zhěng tào fángzi，fāngbiàn ma？', 'Tôi muốn thuê nguyên căn nhà, có tiện không?', '[{"chinese":"整套","pinyin":"zhěng tào","meaning_vi":"nguyên bộ, nguyên căn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-6ca815796a2f0ca1c9c7aefc.mp3', 4),
    ('请问房间里有什么家具？', 'Qǐngwèn fángjiān lǐ yǒu shénme jiājù？', 'Xin hỏi trong phòng có đồ nội thất gì?', '[{"chinese":"家具","pinyin":"jiājù","meaning_vi":"đồ nội thất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-76573a620e4858cb15ed501f.mp3', 5),
    ('每个月的租金是多少？', 'Měi ge yuè de zūjīn shì duōshǎo？', 'Tiền thuê mỗi tháng là bao nhiêu?', '[{"chinese":"租金","pinyin":"zūjīn","meaning_vi":"tiền thuê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-18ed48a71569e9f8c1f43a0d.mp3', 6),
    ('押金需要交多少？', 'Yājīn xūyào jiāo duōshǎo？', 'Tiền đặt cọc cần nộp bao nhiêu?', '[{"chinese":"押金","pinyin":"yājīn","meaning_vi":"tiền đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-85cb890df8e1fe8813b2c9e2.mp3', 7),
    ('租金可以商量吗？', 'Zūjīn kěyǐ shāngliáng ma？', 'Tiền thuê có thể thương lượng không?', '[{"chinese":"商量","pinyin":"shāngliáng","meaning_vi":"thương lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-79ddefafce7960dc20e81c92.mp3', 8),
    ('合同里的条款请仔细看。', 'Hétong lǐ de tiáokuǎn qǐng zǐxì kàn。', 'Xin vui lòng đọc kỹ các điều khoản trong hợp đồng.', '[{"chinese":"条款","pinyin":"tiáokuǎn","meaning_vi":"điều khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-460f9984322d315a6f586fc5.mp3', 9),
    ('我们什么时候签合同？', 'Wǒmen shénme shíhou qiān hétong？', 'Chúng ta sẽ ký hợp đồng vào lúc nào?', '[{"chinese":"签","pinyin":"qiān","meaning_vi":"ký"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-4582a897f57879bef09611a8.mp3', 10),
    ('请把钥匙交给我。', 'Qǐng bǎ yàoshi jiāo gěi wǒ。', 'Xin hãy đưa chìa khóa cho tôi.', '[{"chinese":"钥匙","pinyin":"yàoshi","meaning_vi":"chìa khóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-7d658cbb7247150b761220b2.mp3', 11),
    ('我打算下个月搬进去。', 'Wǒ dǎsuàn xià ge yuè bān jìnqù。', 'Tôi dự định tháng sau chuyển vào ở.', '[{"chinese":"搬进去","pinyin":"bān jìnqù","meaning_vi":"chuyển vào"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-f25ab007aa9bf80c51403265.mp3', 12),
    ('可以帮我续租合同吗？', 'Kěyǐ bāng wǒ xù zū hétong ma？', 'Có thể giúp tôi gia hạn hợp đồng thuê nhà không?', '[{"chinese":"续租","pinyin":"xù zū","meaning_vi":"gia hạn thuê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-9dab126bcb8b270a983773b9.mp3', 13),
    ('我想提前一个月退房。', 'Wǒ xiǎng tíqián yí ge yuè tuì fáng。', 'Tôi muốn trả nhà trước một tháng.', '[{"chinese":"退房","pinyin":"tuì fáng","meaning_vi":"trả nhà"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-a2b822540089569ece84c2e5.mp3', 14),
    ('退房后什么时候能收回押金？', 'Tuì fáng hòu shénme shíhou néng shōu huí yājīn？', 'Sau khi trả nhà thì khi nào có thể nhận lại tiền cọc?', '[{"chinese":"收回","pinyin":"shōu huí","meaning_vi":"nhận lại, thu hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-09927da97a4989dc818bc549.mp3', 15),
    ('这套房子可以合租吗？', 'Zhè tào fángzi kěyǐ hézū ma？', 'Căn nhà này có thể thuê chung không?', '[{"chinese":"合租","pinyin":"hézū","meaning_vi":"thuê chung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-30b0b7775f446497956bbd23.mp3', 16),
    ('房东联系方式是多少？', 'Fángdōng liánxì fāngshì shì duōshǎo？', 'Số điện thoại liên hệ chủ nhà là bao nhiêu?', '[{"chinese":"房东","pinyin":"fángdōng","meaning_vi":"chủ nhà"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-517f54af405fe2050996fd14.mp3', 17),
    ('看房时间可以改吗？', 'Kàn fáng shíjiān kěyǐ gǎi ma？', 'Thời gian xem nhà có thể thay đổi không?', '[{"chinese":"时间","pinyin":"shíjiān","meaning_vi":"thời gian"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-80ca3a981bb028f8eaa20dc6.mp3', 18),
    ('房租什么时候交？', 'Fángzū shénme shíhou jiāo？', 'Khi nào phải đóng tiền thuê nhà?', '[{"chinese":"房租","pinyin":"fángzū","meaning_vi":"tiền thuê nhà"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-d648c67baa2b5144a0babd56.mp3', 19),
    ('合同可以续签半年吗？', 'Hétong kěyǐ xù qiān bàn nián ma？', 'Hợp đồng có thể gia hạn thêm nửa năm không?', '[{"chinese":"续签","pinyin":"xù qiān","meaning_vi":"gia hạn ký"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-dda523a9193faa71677c5032.mp3', 20),
    ('请告诉我入住的具体日期。', 'Qǐng gàosu wǒ rùzhù de jùtǐ rìqī。', 'Xin hãy cho tôi biết ngày cụ thể chuyển vào ở.', '[{"chinese":"入住","pinyin":"rùzhù","meaning_vi":"chuyển vào ở"},{"chinese":"具体","pinyin":"jùtǐ","meaning_vi":"cụ thể"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-37b83cbf6c864f82b27386c1.mp3', 21),
    ('合同上没有写维修责任吗？', 'Hétong shàng méiyǒu xiě wéixiū zérèn ma？', 'Trong hợp đồng không viết trách nhiệm sửa chữa chứ?', '[{"chinese":"维修","pinyin":"wéixiū","meaning_vi":"sửa chữa"},{"chinese":"责任","pinyin":"zérèn","meaning_vi":"trách nhiệm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b3f7ff839cd07b8222fc3203.mp3', 22),
    ('退房时需要做什么？', 'Tuì fáng shí xūyào zuò shénme？', 'Khi trả nhà cần làm gì?', '[{"chinese":"退房","pinyin":"tuì fáng","meaning_vi":"trả nhà"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-7059bcbfa0021a6017378d56.mp3', 23),
    ('请问这里的隔音效果怎么样？', 'Qǐngwèn zhèlǐ de géyīn xiàoguǒ zěnmeyàng?', 'Xin hỏi khả năng cách âm ở đây thế nào?', '[{"chinese":"隔音效果","pinyin":"géyīn xiàoguǒ","meaning_vi":"khả năng cách âm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-70f3c18b8498811b2d164af3.mp3', 24),
    ('这个合同一共几页？', 'Zhè ge hétong yí gòng jǐ yè？', 'Hợp đồng này tổng cộng bao nhiêu trang?', '[{"chinese":"合同","pinyin":"hétong","meaning_vi":"hợp đồng"},{"chinese":"一共","pinyin":"yí gòng","meaning_vi":"tổng cộng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-d7f74d57736504027192403b.mp3', 25),
    ('我想了解一下房子的朝向。', 'Wǒ xiǎng liǎojiě yíxià fángzi de cháoxiàng。', 'Tôi muốn tìm hiểu về hướng nhà một chút.', '[{"chinese":"了解","pinyin":"liǎojiě","meaning_vi":"tìm hiểu"},{"chinese":"朝向","pinyin":"cháoxiàng","meaning_vi":"hướng, phương hướng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-251f8ef9069225776fcea7ea.mp3', 26),
    ('您方便告诉我房子的面积吗？', 'Nín fāngbiàn gàosu wǒ fángzi de miànjī ma？', 'Anh/chị có thể cho tôi biết diện tích nhà không?', '[{"chinese":"面积","pinyin":"miànjī","meaning_vi":"diện tích"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-65dd2e26b140605588748e12.mp3', 27),
    ('请问您接受养宠物吗？', 'Qǐngwèn nín jiēshòu yǎng chǒngwù ma？', 'Xin hỏi anh/chị có chấp nhận nuôi thú cưng không?', '[{"chinese":"接受","pinyin":"jiēshòu","meaning_vi":"chấp nhận"},{"chinese":"宠物","pinyin":"chǒngwù","meaning_vi":"thú cưng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-93df9e52bca013cbec6c14af.mp3', 28),
    ('这个公寓离地铁站走路只要十分钟。', 'Zhè ge gōngyù lí dìtiě zhàn zǒu lù zhǐ yào shí fēnzhōng.', 'Căn hộ này cách ga tàu điện ngầm chỉ mười phút đi bộ.', '[{"chinese":"公寓","pinyin":"gōngyù","meaning_vi":"căn hộ"},{"chinese":"地铁站","pinyin":"dìtiě zhàn","meaning_vi":"ga tàu điện ngầm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-01f6896476d92f408284a109.mp3', 29),
    ('您能告诉我押金是多少吗？', 'Nín néng gàosù wǒ yājīn shì duōshǎo ma?', 'Ông/bà có thể cho tôi biết tiền đặt cọc là bao nhiêu không?', '[{"chinese":"押金","pinyin":"yājīn","meaning_vi":"tiền đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-288bf3f4a3af3f22dae6b8d6.mp3', 30),
    ('请问这个月的电费是多少？', 'Qǐngwèn zhège yuè de diànfèi shì duōshǎo?', 'Xin hỏi tiền điện tháng này là bao nhiêu?', '[{"chinese":"电费","pinyin":"diànfèi","meaning_vi":"tiền điện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-d94f2cc9496e3696aad2234d.mp3', 31),
    ('水费可以在哪里交？', 'Shuǐfèi kěyǐ zài nǎlǐ jiāo?', 'Tiền nước có thể đóng ở đâu vậy?', '[{"chinese":"水费","pinyin":"shuǐfèi","meaning_vi":"tiền nước"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-1caecc54590ad2e6e3a56903.mp3', 32),
    ('燃气费用什么时候结算？', 'Ránqì fèiyòng shénme shíhòu jiésuàn?', 'Phí gas khi nào thanh toán?', '[{"chinese":"燃气","pinyin":"ránqì","meaning_vi":"khí ga"},{"chinese":"费用","pinyin":"fèiyòng","meaning_vi":"chi phí, phí"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-a72a9803c3c7a27729e033b2.mp3', 33),
    ('物业费每个月需要交多少？', 'Wùyè fèi měi gè yuè xūyào jiāo duōshǎo?', 'Phí quản lý mỗi tháng phải đóng bao nhiêu?', '[{"chinese":"物业费","pinyin":"wùyè fèi","meaning_vi":"phí quản lý chung cư"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-2fbc1c3e1ff773c941764608.mp3', 34),
