    ('我想买到火车站的地铁票。', 'Wǒ xiǎng mǎi dào huǒchē zhàn de dìtiě piào.', 'Tôi muốn mua vé tàu điện đến ga tàu hỏa.', '[{"chinese":"地铁票","pinyin":"dìtiě piào","meaning_vi":"vé tàu điện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-d171fd599ab036398e7e28a7.mp3', 134),
    ('请问换乘这条地铁线路怎么走？', 'Qǐngwèn huànchéng zhè tiáo dìtiě xiànlù zěnme zǒu？', 'Xin hỏi đi đổi tuyến tàu điện này như thế nào?', '[{"chinese":"换乘","pinyin":"huànchéng","meaning_vi":"đổi tuyến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-6fdff0a7b94d7060337d38f6.mp3', 135),
    ('请问如何添加新的微信联系人？', 'Qǐngwèn rúhé tiānjiā xīn de Wēixìn liánxìrén？', 'Xin hỏi làm sao để thêm bạn mới trên WeChat?', '[{"chinese":"添加","pinyin":"tiānjiā","meaning_vi":"thêm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-889f78b7e6d0750369133833.mp3', 136),
    ('我用微信扫一扫功能扫描这个二维码。', 'Wǒ yòng Wēixìn sǎo yī sǎo gōngnéng sǎomiáo zhège èrwéimǎ.', 'Tôi dùng WeChat quét mã QR này.', '[{"chinese":"扫描","pinyin":"sǎomiáo","meaning_vi":"quét"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-ebadff459051bd5a0aad1565.mp3', 137),
    ('请你发送当前位置给我好吗？', 'Qǐng nǐ fāsòng dāngqián wèizhì gěi wǒ hǎo ma？', 'Bạn vui lòng gửi vị trí hiện tại cho tôi được không?', '[{"chinese":"位置","pinyin":"wèizhì","meaning_vi":"vị trí"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-4a18cef185cca3f6c384e590.mp3', 138),
    ('我想给朋友发一条语音消息。', 'Wǒ xiǎng gěi péngyǒu fā yītiáo yǔyīn xiāoxī.', 'Tôi muốn gửi một tin nhắn thoại cho bạn.', '[{"chinese":"语音","pinyin":"yǔyīn","meaning_vi":"thông điệp thoại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-a7566c91e2df81657bc5a702.mp3', 139),
    ('可以帮我用微信视频通话吗？', 'Kěyǐ bāng wǒ yòng Wēixìn shìpín tōnghuà ma？', 'Bạn có thể giúp tôi gọi video trên WeChat không?', '[{"chinese":"视频通话","pinyin":"shìpín tōnghuà","meaning_vi":"gọi video"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-f9dc4974d88eccb3d881b715.mp3', 140),
    ('我已经加入了他们的微信群聊。', 'Wǒ yǐjīng jiārùle tāmen de Wēixìn qúnliáo.', 'Tôi đã tham gia nhóm chat WeChat của họ.', '[{"chinese":"群聊","pinyin":"qúnliáo","meaning_vi":"nhóm chat"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-4d06d561f541027f41d0496d.mp3', 141),
    ('微信群消息可以设置为免打扰。', 'Wēixìn qún xiāoxī kěyǐ shèzhì wèi miǎn dǎrǎo.', 'Tin nhắn nhóm WeChat có thể được đặt chế độ không làm phiền.', '[{"chinese":"免打扰","pinyin":"miǎn dǎrǎo","meaning_vi":"không làm phiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-2ee2c1c72544ee93665eb2be.mp3', 142),
    ('我用微信支付了房租费用。', 'Wǒ yòng Wēixìn zhīfùle fángzū fèiyòng.', 'Tôi đã thanh toán tiền thuê nhà qua WeChat Pay.', '[{"chinese":"支付","pinyin":"zhīfù","meaning_vi":"thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-0091ab26cd111f623e4dd558.mp3', 143),
    ('请用微信扫一扫支付这个二维码。', 'Qǐng yòng Wēixìn sǎo yī sǎo zhīfù zhège èrwéimǎ.', 'Xin dùng WeChat quét mã QR để thanh toán.', '[{"chinese":"支付","pinyin":"zhīfù","meaning_vi":"thanh toán"},{"chinese":"二维码","pinyin":"èrwéimǎ","meaning_vi":"mã QR"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-9dc6226ef00e336a4f583e14.mp3', 144),
    ('请你确认付款金额是否正确？', 'Qǐng nǐ quèrèn fùkuǎn jīn’é shìfǒu zhèngquè？', 'Bạn vui lòng xác nhận số tiền thanh toán có chính xác không?', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"金额","pinyin":"jīn’é","meaning_vi":"số tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-0463a45f3d0c5d891374b4ca.mp3', 145),
    ('抱歉，您的付款失败了，请重试。', 'Bàoqiàn, nín de fùkuǎn shībài le, qǐng chóngshì.', 'Xin lỗi, thanh toán của bạn thất bại, vui lòng thử lại.', '[{"chinese":"失败","pinyin":"shībài","meaning_vi":"thất bại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-ec5c8d2391cc3335bc0f82ae.mp3', 146),
    ('余额不足，请先充值后再付款。', 'Yú''é bùzú, qǐng xiān chōngzhí hòu zài fùkuǎn.', 'Số dư không đủ, vui lòng nạp tiền rồi thanh toán.', '[{"chinese":"余额","pinyin":"yú''é","meaning_vi":"số dư"},{"chinese":"充值","pinyin":"chōngzhí","meaning_vi":"nạp tiền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b944c1991456b89aba8b6602.mp3', 147),
    ('我需要更改微信绑定的手机号。', 'Wǒ xūyào gēnggǎi Wēixìn bǎngdìng de shǒujī hàomǎ.', 'Tôi cần đổi số điện thoại đã liên kết với WeChat.', '[{"chinese":"更改","pinyin":"gēnggǎi","meaning_vi":"đổi"},{"chinese":"手机号","pinyin":"shǒujī hàomǎ","meaning_vi":"số điện thoại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-385d1f90b38382ce4f2c99be.mp3', 148),
    ('忘记密码了，如何找回微信账户？', 'Wàngjì mìmǎ le, rúhé zhǎohuí Wēixìn zhànghù？', 'Quên mật khẩu, làm sao lấy lại tài khoản WeChat?', '[{"chinese":"密码","pinyin":"mìmǎ","meaning_vi":"mật khẩu"},{"chinese":"找回","pinyin":"zhǎohuí","meaning_vi":"lấy lại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-d864c45759f4cb828b788f1a.mp3', 149),
    ('我的微信账号被锁了，请问怎么解锁？', 'Wǒ de Wēixìn zhànghào bèi suǒ le, qǐngwèn zěnme jiěsuǒ？', 'Tài khoản WeChat của tôi bị khóa, xin hỏi làm sao mở khóa?', '[{"chinese":"账号","pinyin":"zhànghào","meaning_vi":"tài khoản"},{"chinese":"锁","pinyin":"suǒ","meaning_vi":"khóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-a0561cfbe25e90d8dff4a8f8.mp3', 150),
    ('在微信聊天时，请说慢一点好吗？', 'Zài Wēixìn liáotiān shí, qǐng shuō màn yīdiǎn hǎo ma？', 'Khi trò chuyện trên WeChat, bạn nói chậm một chút được không?', '[{"chinese":"聊天","pinyin":"liáotiān","meaning_vi":"trò chuyện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-bec3f7727b4547f38c868fd2.mp3', 151),
    ('我可以借用你的手机发消息吗？', 'Wǒ kěyǐ jièyòng nǐ de shǒujī fā xiāoxī ma？', 'Tôi có thể mượn điện thoại của bạn gửi tin nhắn không?', '[{"chinese":"借用","pinyin":"jièyòng","meaning_vi":"mượn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-5867fa41612b35e38bf84e8e.mp3', 152),
    ('微信支持多种语言翻译功能，非常方便。', 'Wēixìn zhīchí duō zhǒng yǔyán fānyì gōngnéng, fēicháng fāngbiàn.', 'WeChat hỗ trợ nhiều ngôn ngữ dịch, rất tiện lợi.', '[{"chinese":"翻译","pinyin":"fānyì","meaning_vi":"dịch thuật"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-08d9175743fd089fad51fc99.mp3', 153),
    ('我用微信付款以后会收到电子发票。', 'Wǒ yòng Wēixìn fùkuǎn yǐhòu huì shōudào diànzǐ fāpiào.', 'Sau khi thanh toán bằng WeChat, tôi sẽ nhận được hóa đơn điện tử.', '[{"chinese":"电子发票","pinyin":"diànzǐ fāpiào","meaning_vi":"hóa đơn điện tử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-996b67a4fcc6d0a508587180.mp3', 154),
    ('请您帮我检查一下微信支付的安全设置。', 'Qǐng nín bāng wǒ jiǎnchá yīxià Wēixìn zhīfù de ānquán shèzhì.', 'Xin bạn giúp tôi kiểm tra cài đặt bảo mật của WeChat Pay.', '[{"chinese":"安全","pinyin":"ānquán","meaning_vi":"an toàn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-7dd1b77a4631eb528306538a.mp3', 155),
    ('请问这件商品多少钱？', 'Qǐng wèn zhè jiàn shāngpǐn duōshǎo qián？', 'Xin hỏi món hàng này bao nhiêu tiền?', '[{"chinese":"商品","pinyin":"shāngpǐn","meaning_vi":"món hàng, sản phẩm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-9f6d3a1d0ecb388d7e2e0365.mp3', 156),
    ('超市里哪儿有卖面包？', 'Chāoshì lǐ nǎr yǒu mài miànbāo？', 'Bánh mì bán ở đâu trong siêu thị?', '[{"chinese":"超市","pinyin":"chāoshì","meaning_vi":"siêu thị"},{"chinese":"卖","pinyin":"mài","meaning_vi":"bán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-10d90f96204abaaf454a871d.mp3', 157),
    ('买东西可以用微信支付吗？', 'Mǎi dōngxi kěyǐ yòng Wēixìn zhīfù ma？', 'Mua hàng có thể dùng thanh toán WeChat được không?', '[{"chinese":"支付","pinyin":"zhīfù","meaning_vi":"thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-db78e1e1bdfe8c0b98b488b4.mp3', 158),
    ('请问哪里有最近的药店？', 'Qǐng wèn nǎlǐ yǒu zuìjìn de yàodiàn？', 'Xin hỏi gần đây có hiệu thuốc nào?', '[{"chinese":"药店","pinyin":"yàodiàn","meaning_vi":"hiệu thuốc"},{"chinese":"最近","pinyin":"zuìjìn","meaning_vi":"gần đây"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-41799cf45b064bb088b30d17.mp3', 159),
    ('我想买感冒药，请推荐一下。', 'Wǒ xiǎng mǎi gǎnmào yào，qǐng tuījiàn yīxià。', 'Tôi muốn mua thuốc cảm, xin hãy giới thiệu giúp.', '[{"chinese":"感冒药","pinyin":"gǎnmào yào","meaning_vi":"thuốc cảm"},{"chinese":"推荐","pinyin":"tuījiàn","meaning_vi":"giới thiệu, đề xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-edfa29fc1e29056040b5b3fe.mp3', 160),
    ('超市里有塑料袋吗？', 'Chāoshì lǐ yǒu sùliào dài ma？', 'Trong siêu thị có túi nhựa không?', '[{"chinese":"塑料袋","pinyin":"sùliào dài","meaning_vi":"túi nhựa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-f13b3c010fa3cff739631ba2.mp3', 161),
    ('请帮我称一下这些水果。', 'Qǐng bāng wǒ chēng yīxià zhèxiē shuǐguǒ。', 'Xin giúp tôi cân những loại hoa quả này.', '[{"chinese":"称","pinyin":"chēng","meaning_vi":"cân"},{"chinese":"水果","pinyin":"shuǐguǒ","meaning_vi":"hoa quả"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-bc0accee656e4f72e00bb90f.mp3', 162),
    ('洗衣店几点开始营业？', 'Xǐyī diàn jǐ diǎn kāishǐ yíngyè？', 'Tiệm giặt đồ mấy giờ mở cửa?', '[{"chinese":"洗衣店","pinyin":"xǐyī diàn","meaning_vi":"tiệm giặt đồ"},{"chinese":"营业","pinyin":"yíngyè","meaning_vi":"mở cửa kinh doanh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-119ac5896941e0bdf603a308.mp3', 163),
    ('我的衣服可以烘干吗？', 'Wǒ de yīfu kěyǐ hōnggān ma？', 'Quần áo của tôi có thể sấy khô được không?', '[{"chinese":"烘干","pinyin":"hōnggān","meaning_vi":"sấy khô"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-77776a33988d7513c1c5fefb.mp3', 164),
    ('我想预约明天剪头发。', 'Wǒ xiǎng yùyuē míngtiān jiǎn tóufǎ。', 'Tôi muốn đặt lịch cắt tóc vào ngày mai.', '[{"chinese":"预约","pinyin":"yùyuē","meaning_vi":"đặt lịch hẹn"},{"chinese":"剪头发","pinyin":"jiǎn tóufǎ","meaning_vi":"cắt tóc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-23fac1fb209b1bfc6a1379d2.mp3', 165),
    ('附近有打印店吗？', 'Fùjìn yǒu dǎyìn diàn ma？', 'Gần đây có cửa hàng in ấn không?', '[{"chinese":"打印店","pinyin":"dǎyìn diàn","meaning_vi":"cửa hàng in ấn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-8326287a50eee4ece1e3f9b2.mp3', 166),
    ('请帮我寄这个包裹。', 'Qǐng bāng wǒ jì zhège bāoguǒ。', 'Xin giúp tôi gửi bưu phẩm này.', '[{"chinese":"寄","pinyin":"jì","meaning_vi":"gửi"},{"chinese":"包裹","pinyin":"bāoguǒ","meaning_vi":"bưu phẩm, gói hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-c851de59cff6467163775d0b.mp3', 167),
    ('我想买一张手机SIM卡。', 'Wǒ xiǎng mǎi yī zhāng shǒujī SIM kǎ。', 'Tôi muốn mua một thẻ SIM điện thoại.', '[{"chinese":"手机","pinyin":"shǒujī","meaning_vi":"điện thoại"},{"chinese":"SIM卡","pinyin":"SIM kǎ","meaning_vi":"thẻ SIM"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-6623d0df4aa92c590eca7783.mp3', 168),
    ('怎么开通移动数据套餐？', 'Zěnme kāitōng yídòng shùjù tàocān？', 'Làm thế nào để đăng ký gói dữ liệu di động?', '[{"chinese":"开通","pinyin":"kāitōng","meaning_vi":"mở, đăng ký"},{"chinese":"套餐","pinyin":"tàocān","meaning_vi":"gói dịch vụ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-eb6beb7963ca0b4801ff0d69.mp3', 169),
    ('药店几点关门？', 'Yàodiàn jǐ diǎn guānmén？', 'Hiệu thuốc mấy giờ đóng cửa?', '[{"chinese":"关门","pinyin":"guānmén","meaning_vi":"đóng cửa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-7d955115375d7ab716082ac4.mp3', 170),
    ('请给我开一张发票。', 'Qǐng gěi wǒ kāi yī zhāng fāpiào。', 'Xin cho tôi xin một hóa đơn.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-be4118b2bd3afeb4cf009ede.mp3', 171),
    ('请问洗衣服务多少钱？', 'Qǐng wèn xǐyī fúwù duōshǎo qián？', 'Xin hỏi dịch vụ giặt đồ bao nhiêu tiền?', '[{"chinese":"服务","pinyin":"fúwù","meaning_vi":"dịch vụ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-74438ba0a9b1106437c10e33.mp3', 172),
    ('请问这附近哪里可以买菜？', 'Qǐng wèn zhè fùjìn nǎlǐ kěyǐ mǎi cài？', 'Xin hỏi gần đây chỗ nào có thể mua rau?', '[{"chinese":"附近","pinyin":"fùjìn","meaning_vi":"gần đây"},{"chinese":"买菜","pinyin":"mǎi cài","meaning_vi":"mua rau, mua đồ ăn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-fdb5ff4553a28ac26089c925.mp3', 173),
    ('可以给我塑料袋吗？', 'Kěyǐ gěi wǒ sùliào dài ma？', 'Bạn có thể cho tôi túi nhựa không?', '[{"chinese":"塑料袋","pinyin":"sùliào dài","meaning_vi":"túi nhựa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-c79339ce24292457b8864663.mp3', 174),
    ('包裹可以放在门口吗？', 'Bāoguǒ kěyǐ fàng zài ménkǒu ma？', 'Gói hàng có thể để ở cửa được không?', '[{"chinese":"包裹","pinyin":"bāoguǒ","meaning_vi":"bưu phẩm, gói hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b9d222005d914fe1985dbb39.mp3', 175),
    ('请您说慢一点，我听不太清楚。', 'Qǐng nín shuō màn yīdiǎn, wǒ tīng bù tài qīngchǔ.', 'Xin ông/bà nói chậm một chút, tôi nghe không rõ lắm.', '[{"chinese":"说慢一点","pinyin":"shuō màn yīdiǎn","meaning_vi":"nói chậm một chút"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-1a9e0092371d3ef67151466a.mp3', 176),
    ('对不起，您能再说一遍吗？', 'Duìbùqǐ, nín néng zài shuō yí biàn ma?', 'Xin lỗi, ông/bà có thể nói lại một lần nữa được không?', '[{"chinese":"再说","pinyin":"zài shuō","meaning_vi":"nói lại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-176dc6cfc7b9ec6842353a86.mp3', 177),
    ('我不太明白您的意思，请帮我解释。', 'Wǒ bù tài míngbái nín de yìsi, qǐng bāng wǒ jiěshì.', 'Tôi không hiểu ý của ông/bà lắm, xin hãy giúp tôi giải thích.', '[{"chinese":"明白","pinyin":"míngbái","meaning_vi":"hiểu rõ"},{"chinese":"解释","pinyin":"jiěshì","meaning_vi":"giải thích"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-35c3b3b893904ef67ef079bf.mp3', 178),
    ('您可以帮我写一下地址吗？', 'Nín kěyǐ bāng wǒ xiě yíxià dìzhǐ ma?', 'Ông/bà có thể giúp tôi viết địa chỉ được không?', '[{"chinese":"写","pinyin":"xiě","meaning_vi":"viết"},{"chinese":"地址","pinyin":"dìzhǐ","meaning_vi":"địa chỉ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-cd12ae01b841293ac8a5cb12.mp3', 179),
    ('能借我用一下您的手机吗？', 'Néng jiè wǒ yòng yíxià nín de shǒujī ma?', 'Bạn có thể cho tôi mượn điện thoại của bạn một chút được không?', '[{"chinese":"借","pinyin":"jiè","meaning_vi":"mượn"},{"chinese":"手机","pinyin":"shǒujī","meaning_vi":"điện thoại di động"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-215c090ce2edae497b1d6443.mp3', 180),
    ('我的手机没电了，能充一下电吗？', 'Wǒ de shǒujī méi diàn le, néng chōng yíxià diàn ma?', 'Điện thoại của tôi hết pin rồi, có thể sạc pin một chút không?', '[{"chinese":"没电","pinyin":"méi diàn","meaning_vi":"hết pin"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-6ba93a59362d9ac14b1fdb07.mp3', 181),
    ('我昨天把钱包弄丢了，请问应该怎么办？', 'Wǒ zuótiān bǎ qiánbāo nòng diū le, qǐngwèn yīnggāi zěnme bàn?', 'Hôm qua tôi làm mất ví, xin hỏi tôi nên làm gì?', '[{"chinese":"弄丢","pinyin":"nòng diū","meaning_vi":"làm mất"},{"chinese":"怎么办","pinyin":"zěnme bàn","meaning_vi":"làm thế nào"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-9e73cf73cc6325a4612d50ac.mp3', 182),
    ('我的护照不见了，您能帮我吗？', 'Wǒ de hùzhào bú jiàn le, nín néng bāng wǒ ma?', 'Hộ chiếu của tôi bị mất rồi, ông/bà có thể giúp tôi không?', '[{"chinese":"护照","pinyin":"hùzhào","meaning_vi":"hộ chiếu"},{"chinese":"不见","pinyin":"bú jiàn","meaning_vi":"biến mất, không thấy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-a68320516d243f521cce215c.mp3', 183),
    ('请问最近的派出所在哪里？', 'Qǐngwèn zuìjìn de pàichūsuǒ zài nǎlǐ?', 'Xin hỏi đồn cảnh sát gần nhất ở đâu?', '[{"chinese":"派出所","pinyin":"pàichūsuǒ","meaning_vi":"đồn cảnh sát"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-08895208e745435bd1e82e07.mp3', 184),
    ('我发烧了，哪里有医院可以看病？', 'Wǒ fāshāo le, nǎlǐ yǒu yīyuàn kěyǐ kànbìng?', 'Tôi bị sốt, ở đâu có bệnh viện để khám bệnh?', '[{"chinese":"发烧","pinyin":"fāshāo","meaning_vi":"bị sốt"},{"chinese":"医院","pinyin":"yīyuàn","meaning_vi":"bệnh viện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-30078af61ecfbb2bc7753b73.mp3', 185),
    ('我需要一位翻译，能帮忙找吗？', 'Wǒ xūyào yī wèi fānyì, néng bāngmáng zhǎo ma?', 'Tôi cần một phiên dịch, có thể giúp tôi tìm được không?', '[{"chinese":"翻译","pinyin":"fānyì","meaning_vi":"phiên dịch"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b17d37b49c4a680c8c525561.mp3', 186),
    ('楼上邻居的声音太大了，请帮我反映一下。', 'Lóu shàng línjū de shēngyīn tài dà le, qǐng bāng wǒ fǎnyìng yíxià.', 'Tiếng ồn từ hàng xóm trên lầu quá lớn, xin hãy giúp tôi phản ánh một chút.', '[{"chinese":"声音","pinyin":"shēngyīn","meaning_vi":"âm thanh, tiếng"},{"chinese":"反映","pinyin":"fǎnyìng","meaning_vi":"phản ánh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-f1ded8aba55ec309899fdd32.mp3', 187),
    ('我不在家时，可以请邻居帮忙收快递吗？', 'Wǒ bú zài jiā shí, kěyǐ qǐng línjū bāngmáng shōu kuàidì ma?', 'Khi tôi không ở nhà, có thể nhờ hàng xóm nhận hàng giúp không?', '[{"chinese":"邻居","pinyin":"línjū","meaning_vi":"hàng xóm"},{"chinese":"收快递","pinyin":"shōu kuàidì","meaning_vi":"nhận hàng giao"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b06737b7a9d8f19dfd4f7c8a.mp3', 188),
    ('对服务不满意，我想提出投诉。', 'Duì fúwù bù mǎnyì, wǒ xiǎng tíchū tóusù.', 'Tôi không hài lòng với dịch vụ, tôi muốn khiếu nại.', '[{"chinese":"投诉","pinyin":"tóusù","meaning_vi":"khiếu nại"},{"chinese":"服务","pinyin":"fúwù","meaning_vi":"dịch vụ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-af9d825d3cdb2059f460dec9.mp3', 189),
    ('可以帮我换一个房间吗？这个房间有问题。', 'Kěyǐ bāng wǒ huàn yí gè fángjiān ma? Zhège fángjiān yǒu wèntí.', 'Bạn có thể giúp tôi đổi phòng không? Căn phòng này có vấn đề.', '[{"chinese":"换","pinyin":"huàn","meaning_vi":"đổi"},{"chinese":"房间","pinyin":"fángjiān","meaning_vi":"phòng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-34c1132bdc51c59ebb8fffb5.mp3', 190),
    ('门锁坏了，我进不了门，请尽快帮我开门。', 'Mén suǒ huài le, wǒ jìn bù liǎo mén, qǐng jǐnkuài bāng wǒ kāi mén.', 'Ổ khóa cửa bị hỏng, tôi không vào được cửa, xin giúp tôi mở cửa càng sớm càng tốt.', '[{"chinese":"门锁","pinyin":"mén suǒ","meaning_vi":"ổ khóa cửa"},{"chinese":"坏","pinyin":"huài","meaning_vi":"hỏng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-ec4838bd4e4b46af4a3792c3.mp3', 191),
    ('遇到紧急情况，请问报警电话是多少？', 'Yù dào jǐnjí qíngkuàng, qǐngwèn bàojǐng diànhuà shì duōshǎo?', 'Gặp tình huống khẩn cấp, xin hỏi số điện thoại báo cảnh sát là bao nhiêu?', '[{"chinese":"紧急","pinyin":"jǐnjí","meaning_vi":"khẩn cấp"},{"chinese":"报警","pinyin":"bàojǐng","meaning_vi":"báo cảnh sát"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-426462dfca8cbe6f667e04ff.mp3', 192),
    ('问题已经解决了，谢谢您的帮助。', 'Wèntí yǐjīng jiějué le, xièxiè nín de bāngzhù.', 'Vấn đề đã được giải quyết rồi, cảm ơn sự giúp đỡ của ông/bà.', '[{"chinese":"解决","pinyin":"jiějué","meaning_vi":"giải quyết"},{"chinese":"帮助","pinyin":"bāngzhù","meaning_vi":"giúp đỡ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-b2c86f68974cafa892a41a64.mp3', 193),
    ('非常感谢您的及时帮助。', 'Fēicháng gǎnxiè nín de jíshí bāngzhù.', 'Rất cảm ơn sự giúp đỡ kịp thời của ông/bà.', '[{"chinese":"感谢","pinyin":"gǎnxiè","meaning_vi":"cảm ơn"},{"chinese":"及时","pinyin":"jíshí","meaning_vi":"kịp thời"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-ed373cb5085966b003f66d5e.mp3', 194),
    ('外面的噪音太大了，影响休息，请帮我反映。', 'Wàimiàn de zàoyīn tài dà le, yǐngxiǎng xiūxí, qǐng bāng wǒ fǎnyìng.', 'Tiếng ồn bên ngoài quá lớn, ảnh hưởng đến nghỉ ngơi, xin hãy giúp tôi phản ánh.', '[{"chinese":"噪音","pinyin":"zàoyīn","meaning_vi":"tiếng ồn"},{"chinese":"影响","pinyin":"yǐngxiǎng","meaning_vi":"ảnh hưởng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-ada05ebeb11347ce59cfd525.mp3', 195),
    ('我被锁在门外了，请尽快帮我开门。', 'Wǒ bèi suǒ zài mén wài le, qǐng jǐnkuài bāng wǒ kāi mén.', 'Tôi bị khóa ngoài cửa, xin nhanh chóng giúp tôi mở cửa.', '[{"chinese":"锁","pinyin":"suǒ","meaning_vi":"khóa"},{"chinese":"门外","pinyin":"mén wài","meaning_vi":"bên ngoài cửa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-0abc0f9becbcbb4a85a45575.mp3', 196),
    ('我的电脑坏了，您能帮我修理吗？', 'Wǒ de diànnǎo huài le, nín néng bāng wǒ xiūlǐ ma?', 'Máy tính của tôi hỏng rồi, ông/bà có thể giúp tôi sửa chữa được không?', '[{"chinese":"电脑","pinyin":"diànnǎo","meaning_vi":"máy tính"},{"chinese":"修理","pinyin":"xiūlǐ","meaning_vi":"sửa chữa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-96817c6a38ad560da54f8d95.mp3', 197),
    ('您可以告诉我最近的药店在哪里吗？', 'Nín kěyǐ gàosu wǒ zuìjìn de yàodiàn zài nǎlǐ ma?', 'Ông/bà có thể cho tôi biết hiệu thuốc gần đây ở đâu không?', '[{"chinese":"药店","pinyin":"yàodiàn","meaning_vi":"hiệu thuốc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-684a928fbf2bd75e82f9ceae.mp3', 198),
    ('请帮我联系快递员，包裹迟到了。', 'Qǐng bāng wǒ liánxì kuàidìyuán, bāoguǒ chídào le.', 'Xin giúp tôi liên hệ với nhân viên giao hàng, kiện hàng bị trễ rồi.', '[{"chinese":"快递员","pinyin":"kuàidìyuán","meaning_vi":"nhân viên giao hàng"},{"chinese":"迟到","pinyin":"chídào","meaning_vi":"đến muộn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-bd7f7e90745ea583db411ace.mp3', 199),
    ('请问附近有公共洗手间吗？', 'Qǐngwèn fùjìn yǒu gōnggòng xǐshǒujiān ma?', 'Xin hỏi gần đây có nhà vệ sinh công cộng không?', '[{"chinese":"公共","pinyin":"gōnggòng","meaning_vi":"công cộng"},{"chinese":"洗手间","pinyin":"xǐshǒujiān","meaning_vi":"nhà vệ sinh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/sinh-hoat-tai-trung-quoc-200-cau/sentence-e4addef1889696d1136f28d6.mp3', 200)
) as card(
  sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
on conflict (template_deck_id, sentence_cn) do update
set
  sentence_pinyin = excluded.sentence_pinyin,
  sentence_vi = excluded.sentence_vi,
  vocab_json = excluded.vocab_json,
  sentence_audio_url = excluded.sentence_audio_url,
  position = excluded.position;

delete from public.template_sentence_cards
where template_deck_id = (
